css:
/* relevant code */
 .svg_filter {
	--a: .7;
	--text-c: rgb(255 165 0);
	--back-c: rgb(25 25 112);
	position: relative;
	/* prevent blending with page backdrop */
	isolation: isolate;
	clip-path: inset(0);
	filter: url(#go);
	
	&::after {
		position: absolute;
		inset: -2em;
		border: solid 1em rgb(0% calc(var(--a)*100%) 0%/ .5);
		box-shadow: 
			inset 0 0 0 1em rgb(from var(--text-c) r g b/ .75), 
			0 0 0 1em rgb(from var(--back-c) r g b/ .25);
		pointer-events: none;
		content: ''
	}
}

 .svg_filter > span {
	padding: .5em;
	border-radius: 5px;
	background: #000;
	color: #fff;
	/* Safari unfortunately still needs the prefix */
	-webkit-box-decoration-break: clone;
	box-decoration-break: clone;
	
	/* only on inner span to work in Firefox */
	span { mix-blend-mode: lighten }
}

/* layout, prettifying/ secondary stuff */
html, body, form, div { display: grid }

html { min-height: 100% }

body {
	place-content: center;
	overflow-x: hidden;
	background: 
		url(https://images.unsplash.com/photo-1491485880348-85d48a9e5312?w=2070) 
		50%/ cover;
	font: clamp(.75em, 5vmin, 2em)/ 1.25 rokkitt, serif
}

/* functionally the same as a style, 
 * take it out of document flow */
svg[height='0'][aria-hidden='true'] { position: fixed }

p, .svg_filter {
	box-sizing: border-box;
	padding: .5em;
	max-width: 30em;
	text-align: center;
}
